1	//! Canonicalization for the three request components accepted by the classifier.
2	//!
3	//! This module deliberately accepts only the unambiguous ASCII subset of HTTP
4	//! authority and path syntax. In particular, IP literals, userinfo, encoded
5	//! separators, malformed percent escapes, and non-ASCII text are rejected.
6	
7	const MAX_METHOD_BYTES: usize = 32;
8	const MAX_REQUEST_PATH_BYTES: usize = 8 * 1024;
9	pub(crate) const MAX_PATTERN_BYTES: usize = 1_024;
10	
11	/// Returns a lowercase DNS hostname without one optional trailing dot or port.
12	pub(crate) fn host(input: &str) -> Option<String> {
13	    if input.is_empty() || !input.is_ascii() || input.contains('@') {
14	        return None;
15	    }
16	
17	    let (name, port) = match input.rsplit_once(':') {
18	        Some((name, port)) => (name, Some(port)),
19	        None => (input, None),
20	    };
21	    // Parsing also rejects values outside the TCP/UDP port range.
22	    if let Some(port) = port
23	        && (!port.bytes().all(|byte| byte.is_ascii_digit()) || port.parse::<u16>().is_err())
24	    {
25	        return None;
26	    }
27	
28	    let name = name.strip_suffix('.').unwrap_or(name);
29	    if !is_dns_name(name)
30	        || name.parse::<std::net::Ipv4Addr>().is_ok()
31	        || is_hex_ipv4_like(name)
32	        || name
33	            .rsplit_once('.')
34	            .map_or(name, |(_, label)| label)
35	            .bytes()
36	            .all(|byte| byte.is_ascii_digit())
37	    {
38	        return None;
39	    }
40	    Some(name.to_ascii_lowercase())
41	}
42	
43	fn is_hex_ipv4_like(value: &str) -> bool {
44	    value.strip_prefix("0x").is_some_and(|digits| {
45	        !digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_hexdigit())
46	    })
47	}
48	
49	/// Validates an HTTP token and folds it to uppercase. HTTP methods are
50	/// case-sensitive on the wire, but clients and servers commonly normalize
51	/// them; folding prevents a lowercase spelling from bypassing a stricter
52	/// uppercase rule and falling through to a broader rule.
53	pub(crate) fn method(input: &str) -> Option<String> {
54	    (1..=MAX_METHOD_BYTES)
55	        .contains(&input.len())
56	        .then_some(())
57	        .filter(|()| input.bytes().all(is_http_token))
58	        .map(|()| input.to_ascii_uppercase())
59	}
60	
61	/// Normalizes a request path. Empty input represents the origin-form `/`.
62	pub(crate) fn request_path(input: &str) -> Option<String> {
63	    let end = input.find(['?', '#']).unwrap_or(input.len());
64	    let path = &input[..end];
65	    if path.len() > MAX_REQUEST_PATH_BYTES {
66	        return None;
67	    }
68	    if path.is_empty() {
69	        return Some("/".into());
70	    }
71	    normalize_path(path, false)
72	}
73	
74	/// Normalizes a configuration path pattern while retaining literal `*`
75	/// wildcards. Query strings and fragments never reach the matcher, so a
76	/// pattern containing one is a configuration mistake.
77	pub(crate) fn pattern_path(input: &str) -> Option<String> {
78	    if input.contains(['?', '#']) {
79	        return None;
80	    }
81	    normalize_path(input, true)
82	}
83	
84	/// Lowercases ASCII letters in a normalized path without changing percent
85	/// escapes. This is used only to detect disagreement with common
86	/// case-insensitive server routers; it never changes the path being matched.
87	pub(crate) fn lowercase_path_outside_escapes(path: &str) -> String {
88	    let bytes = path.as_bytes();
89	    let mut output = String::with_capacity(path.len());
90	    let mut index = 0;
91	    while index < bytes.len() {
92	        if bytes[index] == b'%' {
93	            output.push('%');
94	            if let Some(&byte) = bytes.get(index + 1) {
95	                output.push(char::from(byte));
96	            }
97	            if let Some(&byte) = bytes.get(index + 2) {
98	                output.push(char::from(byte));
99	            }
100	            index = index.saturating_add(3);
101	        } else {
102	            output.push(char::from(bytes[index].to_ascii_lowercase()));
103	            index += 1;
104	        }
105	    }
106	    output
107	}
108	
109	/// Canonical form shared by requests and patterns: unreserved percent escapes
110	/// decoded, other escapes upper-cased, and dot segments removed. Empty path
111	/// segments, backslashes, and encoded separators are rejected because servers
112	/// disagree on what they mean.
113	fn normalize_path(input: &str, pattern: bool) -> Option<String> {
114	    if !input.starts_with('/') {
115	        return None;
116	    }
117	    let decoded = decode_unreserved(input)?;
118	    if decoded.contains("//") || decoded.contains(';') {
119	        return None;
120	    }
121	
122	    // Configuration must describe its path literally. Silently rewriting a
123	    // configured dot segment would make its displayed value disagree with the
124	    // route the matcher actually evaluates.
125	    if pattern
126	        && decoded
127	            .split('/')
128	            .any(|segment| segment == "." || segment == "..")
129	    {
130	        return None;
131	    }
132	    Some(remove_dot_segments(&decoded))
133	}
134	
135	/// RFC 3986 section 6.2.2 normalization: `%72` and `r` are the same path, so
136	/// decode escaped unreserved bytes and upper-case the rest. Decoding happens
137	/// once; `%25` stays `%25`.
138	fn decode_unreserved(input: &str) -> Option<String> {
139	    const HEX: &[u8; 16] = b"0123456789ABCDEF";
140	    let bytes = input.as_bytes();
141	    let mut output = String::with_capacity(input.len());
142	    let mut index = 0;
143	    while let Some(&byte) = bytes.get(index) {
144	        if byte == b'%' {
145	            let hi = hex(*bytes.get(index + 1)?)?;
146	            let lo = hex(*bytes.get(index + 2)?)?;
147	            let value = (hi << 4) | lo;
148	            if matches!(value, b'/' | b'\\') {
149	                return None;
150	            }
151	            if value.is_ascii_alphanumeric() || matches!(value, b'-' | b'.' | b'_' | b'~') {
152	                output.push(char::from(value));
153	            } else {
154	                output.push('%');
155	                output.push(char::from(HEX[usize::from(hi)]));
156	                output.push(char::from(HEX[usize::from(lo)]));
157	            }
158	            index += 3;
159	        } else {
160	            if !byte.is_ascii_graphic() || byte == b'\\' {
161	                return None;
162	            }
163	            output.push(char::from(byte));
164	            index += 1;
165	        }
166	    }
167	    Some(output)
168	}
169	
170	fn hex(byte: u8) -> Option<u8> {
171	    match byte {
172	        b'0'..=b'9' => Some(byte - b'0'),
173	        b'a'..=b'f' => Some(byte - b'a' + 10),
174	        b'A'..=b'F' => Some(byte - b'A' + 10),
175	        _ => None,
176	    }
177	}
178	
179	/// RFC 3986 dot-segment removal for an absolute path without empty segments.
180	/// A stack keeps this linear in the path length.
181	fn remove_dot_segments(input: &str) -> String {
182	    let mut segments = Vec::new();
183	    // A path ending in `.` or `..` names a directory, as `/a/b/..` -> `/a/`.
184	    let mut trailing_slash = false;
185	    for segment in input.split('/').skip(1) {
186	        match segment {
187	            "." => trailing_slash = true,
188	            ".." => {
189	                segments.pop();
190	                trailing_slash = true;
191	            }
192	            _ => {
193	                segments.push(segment);
194	                trailing_slash = false;
195	            }
196	        }
197	    }
198	    let mut output = format!("/{}", segments.join("/"));
199	    if trailing_slash && !output.ends_with('/') {
200	        output.push('/');
201	    }
202	    output
203	}
204	
205	fn is_dns_name(value: &str) -> bool {
206	    !value.is_empty()
207	        && value.len() <= 253
208	        && value.split('.').all(|label| {
209	            !label.is_empty()
210	                && label.len() <= 63
211	                && !label.starts_with('-')
212	                && !label.ends_with('-')
213	                && label
214	                    .bytes()
215	                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
216	        })
217	}
218	
219	fn is_http_token(byte: u8) -> bool {
220	    byte.is_ascii_alphanumeric()
221	        || matches!(
222	            byte,
223	            b'!' | b'#'
224	                | b'$'
225	                | b'%'
226	                | b'&'
227	                | b'\''
228	                | b'*'
229	                | b'+'
230	                | b'-'
231	                | b'.'
232	                | b'^'
233	                | b'_'
234	                | b'`'
235	                | b'|'
236	                | b'~'
237	        )
238	}
