240	#[cfg(test)]
241	mod tests {
242	    use super::{host, lowercase_path_outside_escapes, method, pattern_path, request_path};
243	
244	    #[test]
245	    fn normalizes_hosts_and_rejects_ambiguous_authorities() {
246	        assert_eq!(host("API.Acme.COM.:443"), Some("api.acme.com".into()));
247	        for value in [
248	            "",
249	            "acme.com:",
250	            "acme.com:99999",
251	            "u@acme.com",
252	            "192.0.2.1",
253	            "010.0.0.1",
254	            "127.1",
255	            "1.2.3.4.5",
256	            "0x7f000001",
257	            "[::1]",
258	            "acme..com",
259	            "é.com",
260	            "acme.com..",
261	        ] {
262	            assert_eq!(host(value), None, "{value}");
263	        }
264	    }
265	
266	    #[test]
267	    fn methods_are_tokens_folded_to_upper_case() {
268	        assert_eq!(method("GET"), Some("GET".into()));
269	        assert_eq!(method("delete"), Some("DELETE".into()));
270	        assert_eq!(method("Patch"), Some("PATCH".into()));
271	        for value in ["", "GET ", "GET\n", "é", &"G".repeat(33)] {
272	            assert_eq!(method(value), None, "{value:?}");
273	        }
274	    }
275	
276	    #[test]
277	    fn paths_strip_query_and_normalize_dot_segments() {
278	        assert_eq!(request_path(""), Some("/".into()));
279	        assert_eq!(request_path("/v1/../admin?q=1#x"), Some("/admin".into()));
280	        assert_eq!(request_path("/v1/%2e%2e/admin"), Some("/admin".into()));
281	        assert_eq!(request_path("/a/b/.."), Some("/a/".into()));
282	        assert_eq!(request_path("/a/./b/."), Some("/a/b/".into()));
283	        assert_eq!(request_path("/../../x"), Some("/x".into()));
284	        assert_eq!(request_path("/v1/payments/"), Some("/v1/payments/".into()));
285	        for value in [
286	            "relative", "/x%ZZ", "/x%2f", "/x%5C", "/x\\y", "/é", "/a b", "/a\0", "/v1//x", "//",
287	            "/x;y",
288	        ] {
289	            assert_eq!(request_path(value), None, "{value:?}");
290	        }
291	    }
292	
293	    #[test]
294	    fn paths_decode_unreserved_escapes_only() {
295	        assert_eq!(request_path("/v1/%72efunds"), Some("/v1/refunds".into()));
296	        assert_eq!(request_path("/%7Euser/%5f"), Some("/~user/_".into()));
297	        assert_eq!(request_path("/a%3a%2A"), Some("/a%3A%2A".into()));
298	        assert_eq!(request_path("/a%3Bb"), Some("/a%3Bb".into()));
299	        // No double decoding: `%252e` is a literal `%2e`, not a dot segment.
300	        assert_eq!(
301	            request_path("/a/%252e%252e/b"),
302	            Some("/a/%252e%252e/b".into())
303	        );
304	    }
305	
306	    #[test]
307	    fn lowercases_paths_without_touching_percent_escapes() {
308	        assert_eq!(
309	            lowercase_path_outside_escapes("/V1/%3ARefunds"),
310	            "/v1/%3Arefunds"
311	        );
312	    }
313	
314	    #[test]
315	    fn patterns_retain_wildcards_but_reject_ambiguous_dot_patterns() {
316	        assert_eq!(
317	            pattern_path("/v1/*/refunds/**"),
318	            Some("/v1/*/refunds/**".into())
319	        );
320	        assert_eq!(
321	            pattern_path("/v1/%72efunds/*"),
322	            Some("/v1/refunds/*".into())
323	        );
324	        assert_eq!(pattern_path("/v1/*/../admin"), None);
325	        assert_eq!(pattern_path("/v1/../admin"), None);
326	        assert_eq!(pattern_path("/v1/./admin"), None);
327	        assert_eq!(pattern_path("/v1/*?debug=true"), None);
328	        assert_eq!(pattern_path("/v1//x"), None);
329	        assert_eq!(pattern_path("/v1/refunds;v=1"), None);
330	    }
331	
332	    #[test]
333	    fn long_and_arbitrary_utf8_request_inputs_never_panic() {
334	        assert!(request_path(&format!("/{}", "a".repeat(8_191))).is_some());
335	        assert_eq!(request_path(&format!("/{}", "a".repeat(8_192))), None);
336	        for value in ["\0", "\u{10ffff}", "/\u{10ffff}", "/%"] {
337	            assert_eq!(request_path(value), None, "{value:?}");
338	        }
339	    }
340	}
