1	//! Action classifier: maps `(method, host, path)` to an action class.
2	//!
3	//! Mapping configuration is compiled once. Requests are accepted only when
4	//! their method, authority, and path have an unambiguous ASCII interpretation.
5	
6	mod config;
7	mod matcher;
8	mod normalize;
9	
10	use std::fmt;
11	
12	use config::parse;
13	use matcher::{CompileError, CompiledRule, ConflictCheckError, find_conflict};
14	
15	/// Action classes a rule may name. A rule naming anything else is invalid.
16	pub const ACTION_CLASSES: &[&str] = &[
17	    "payment.read",
18	    "payment.create",
19	    "payment.refund",
20	    "repo.read",
21	    "repo.write",
22	    "communication.external.send",
23	    "llm.inference",
24	];
25	
26	const MAX_TOTAL_RULES: usize = 10_000;
27	const MAX_DIAGNOSTIC_VALUE_BYTES: usize = 256;
28	
29	pub(crate) fn diagnostic_value(value: &str) -> String {
30	    if value.len() <= MAX_DIAGNOSTIC_VALUE_BYTES {
31	        return value.into();
32	    }
33	    let mut end = MAX_DIAGNOSTIC_VALUE_BYTES;
34	    while !value.is_char_boundary(end) {
35	        end -= 1;
36	    }
37	    format!("{}… [truncated]", &value[..end])
38	}
39	
40	/// Why a set of mapping files was rejected. Set and rule indexes are 0-based
41	/// positions in the `sets` slice and the set's `rules` array.
42	#[derive(Debug, thiserror::Error)]
43	pub enum LoadError {
44	    /// One mapping set is invalid on its own. `name` is absent when the set
45	    /// could not be parsed far enough to read it.
46	    #[error("mapping set {set}{}: {error}", display_name(.name))]
47	    InvalidSet {
48	        set: usize,
49	        name: Option<String>,
50	        #[source]
51	        error: SetError,
52	    },
53	    /// Two rules, possibly from different sets, can match the same request
54	    /// with equal specificity but name different action classes.
55	    #[error("{first} and {second} overlap with equal specificity but different action classes")]
56	    ConflictingRules {
57	        first: RuleLocation,
58	        second: RuleLocation,
59	    },
60	    /// Two wildcard patterns require more overlap-analysis state than the
61	    /// loader safely permits. Rejecting prevents configuration-driven memory
62	    /// exhaustion without silently accepting an unresolved ambiguity.
63	    #[error("{first} and {second} require excessive conflict analysis")]
64	    ConflictAnalysisTooComplex {
65	        first: RuleLocation,
66	        second: RuleLocation,
67	    },
68	    #[error("mapping configuration contains more than {limit} rules")]
69	    TooManyRules { limit: usize },
70	}
71	
72	/// The reason a single mapping set is invalid.
73	#[derive(Debug, thiserror::Error)]
74	pub enum SetError {
75	    #[error("invalid TOML: {0}")]
76	    Toml(#[from] toml::de::Error),
77	    #[error("unsupported format version {0}; expected 1")]
78	    UnsupportedFormatVersion(u32),
79	    #[error("{0} must not be empty or malformed")]
80	    InvalidField(&'static str),
81	    #[error("rule {rule} has invalid {field} value {value:?}")]
82	    InvalidRule {
83	        rule: usize,
84	        field: &'static str,
85	        value: String,
86	    },
87	    #[error("rule {rule} names unsupported action class {action_class:?}")]
88	    UnknownActionClass { rule: usize, action_class: String },
89	}
90	
91	/// Where a rule came from, for conflict diagnostics.
92	#[derive(Debug, Clone, PartialEq, Eq)]
93	pub struct RuleLocation {
94	    pub set: usize,
95	    pub name: String,
96	    pub rule: usize,
97	}
98	
99	impl fmt::Display for RuleLocation {
100	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
101	        write!(
102	            f,
103	            "mapping set {} {:?} rule {}",
104	            self.set, self.name, self.rule
105	        )
106	    }
107	}
108	
109	fn display_name(name: &Option<String>) -> String {
110	    name.as_ref()
111	        .map(|name| format!(" {name:?}"))
112	        .unwrap_or_default()
113	}
114	
115	/// An immutable, precompiled collection of mapping rules. Its contents are
116	/// owned strings and therefore it is `Send + Sync` without special handling.
117	pub struct Classifier {
118	    rules: Vec<CompiledRule>,
119	}
120	
121	/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
122	/// are rejected here, so mapping-file ordering never affects classification.
123	pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
124	    let mut rules = Vec::new();
125	    let mut locations = Vec::new();
126	    for (set_index, input) in sets.iter().enumerate() {
127	        let set = parse(input).map_err(|(name, error)| LoadError::InvalidSet {
128	            set: set_index,
129	            name,
130	            error,
131	        })?;
132	        for (rule_index, rule) in set.rules.into_iter().enumerate() {
133	            if rules.len() == MAX_TOTAL_RULES {
134	                return Err(LoadError::TooManyRules {
135	                    limit: MAX_TOTAL_RULES,
136	                });
137	            }
138	            // Validation already ran these checks, so this mapping only
139	            // guards against the two modules drifting apart.
140	            let compiled = CompiledRule::new(
141	                rule.method.as_deref(),
142	                &set.host,
143	                rule.subdomain.as_deref(),
144	                rule.path.as_deref(),
145	                rule.action_class,
146	            )
147	            .map_err(|error| {
148	                let error = match error {
149	                    CompileError::Host => SetError::InvalidRule {
150	                        rule: rule_index,
151	                        field: "subdomain",
152	                        value: diagnostic_value(rule.subdomain.as_deref().unwrap_or_default()),
153	                    },
154	                    CompileError::Method => SetError::InvalidRule {
155	                        rule: rule_index,
156	                        field: "method",
157	                        value: diagnostic_value(rule.method.as_deref().unwrap_or_default()),
158	                    },
159	                    CompileError::Path => SetError::InvalidRule {
160	                        rule: rule_index,
161	                        field: "path",
162	                        value: diagnostic_value(rule.path.as_deref().unwrap_or_default()),
163	                    },
164	                    CompileError::ActionClass(action_class) => SetError::UnknownActionClass {
165	                        rule: rule_index,
166	                        action_class: diagnostic_value(&action_class),
167	                    },
168	                };
169	                LoadError::InvalidSet {
170	                    set: set_index,
171	                    name: Some(set.name.clone()),
172	                    error,
173	                }
174	            })?;
175	            rules.push(compiled);
176	            locations.push(RuleLocation {
177	                set: set_index,
178	                name: set.name.clone(),
179	                rule: rule_index,
180	            });
181	        }
182	    }
183	    match find_conflict(&rules) {
184	        Ok(Some((first, second))) => {
185	            return Err(LoadError::ConflictingRules {
186	                first: locations[first].clone(),
187	                second: locations[second].clone(),
188	            });
189	        }
190	        Ok(None) => {}
191	        Err(ConflictCheckError::TooComplex { first, second }) => {
192	            return Err(LoadError::ConflictAnalysisTooComplex {
193	                first: locations[first].clone(),
194	                second: locations[second].clone(),
195	            });
196	        }
197	    }
198	    Ok(Classifier { rules })
199	}
200	
201	impl Classifier {
202	    /// Classifies a request. Malformed input is deliberately unclassified
203	    /// rather than coerced into a potentially broader rule.
204	    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
205	        let method = normalize::method(method)?;
206	        let host = normalize::host(host)?;
207	        let path = normalize::request_path(path)?;
208	        let class = self.best_match(&method, &host, &path, false);
209	        let lowercase = normalize::lowercase_path_outside_escapes(&path);
210	        let mut alternatives = vec![(lowercase.as_str(), true)];
211	        if let Some(stripped) = path.strip_suffix('/').filter(|rest| !rest.is_empty()) {
212	            alternatives.push((stripped, false));
213	        }
214	        if let Some(stripped) = lowercase.strip_suffix('/').filter(|rest| !rest.is_empty()) {
215	            alternatives.push((stripped, true));
216	        }
217	        for (alternative, case_folded_path) in alternatives {
218	            let alternative_class = self.best_match(&method, &host, alternative, case_folded_path);
219	            if alternative_class.is_some() && alternative_class != class {
220	                return None;
221	            }
222	        }
223	        class
224	    }
225	
226	    fn best_match(
227	        &self,
228	        method: &str,
229	        host: &str,
230	        path: &str,
231	        case_folded_path: bool,
232	    ) -> Option<&str> {
233	        self.rules
234	            .iter()
235	            .filter(|rule| rule.matches(method, host, path, case_folded_path))
236	            .max_by(|left, right| left.compare_specificity(right))
237	            .map(|rule| rule.action_class)
238	    }
239	}
