1	//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.
2	
3	use std::cmp::Ordering;
4	
5	use crate::{ACTION_CLASSES, normalize};
6	
7	#[derive(Debug, Clone, PartialEq, Eq)]
8	pub(crate) enum HostPattern {
9	    Bare(String),
10	    Exact(String),
11	    AnySubdomain(String),
12	}
13	
14	#[derive(Debug, Clone)]
15	pub(crate) struct CompiledRule {
16	    pub(crate) method: Option<String>,
17	    pub(crate) host: HostPattern,
18	    pub(crate) path: Option<String>,
19	    folded_path: Option<String>,
20	    pub(crate) action_class: &'static str,
21	    specificity: Specificity,
22	}
23	
24	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
25	struct Specificity {
26	    host_kind: u8,
27	    host_labels: usize,
28	    path_kind: u8,
29	    literal_count: usize,
30	    inverted_wildcard_count: usize,
31	    literal_prefix: usize,
32	    method: u8,
33	}
34	
35	impl Ord for Specificity {
36	    fn cmp(&self, other: &Self) -> Ordering {
37	        (
38	            self.host_kind,
39	            self.host_labels,
40	            self.path_kind,
41	            self.literal_count,
42	            self.inverted_wildcard_count,
43	            self.literal_prefix,
44	            self.method,
45	        )
46	            .cmp(&(
47	                other.host_kind,
48	                other.host_labels,
49	                other.path_kind,
50	                other.literal_count,
51	                other.inverted_wildcard_count,
52	                other.literal_prefix,
53	                other.method,
54	            ))
55	    }
56	}
