76	
77	impl CompiledRule {
78	    pub(crate) fn new(
79	        method: Option<&str>,
80	        base_host: &str,
81	        subdomain: Option<&str>,
82	        path: Option<&str>,
83	        action_class: String,
84	    ) -> Result<Self, CompileError> {
85	        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
86	        let host = match subdomain {
87	            None => HostPattern::Bare(base_host),
88	            Some("*") => HostPattern::AnySubdomain(base_host),
89	            Some(value) => {
90	                let host = format!("{value}.{base_host}");
91	                HostPattern::Exact(normalize::host(&host).ok_or(CompileError::Host)?)
92	            }
93	        };
94	        let method = match method {
95	            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
96	            None => None,
97	        };
98	        let path = match path {
99	            Some(value) => {
100	                let normalized = normalize::pattern_path(value).ok_or(CompileError::Path)?;
101	                (normalized.len() <= normalize::MAX_PATTERN_BYTES)
102	                    .then_some(normalized)
103	                    .ok_or(CompileError::Path)
104	                    .map(Some)?
105	            }
106	            None => None,
107	        };
108	        let folded_path = path
109	            .as_deref()
110	            .map(normalize::lowercase_path_outside_escapes);
111	        let action_class = ACTION_CLASSES
112	            .iter()
113	            .copied()
114	            .find(|known| *known == action_class)
115	            .ok_or(CompileError::ActionClass(action_class))?;
116	        let specificity = specificity(&host, method.is_some(), path.as_deref());
117	        Ok(Self {
118	            method,
119	            host,
120	            path,
121	            folded_path,
122	            action_class,
123	            specificity,
124	        })
125	    }
126	
127	    pub(crate) fn matches(
128	        &self,
129	        method: &str,
130	        host: &str,
131	        path: &str,
132	        case_folded_path: bool,
133	    ) -> bool {
134	        self.method
135	            .as_deref()
136	            .is_none_or(|expected| expected == method)
137	            && host_matches(&self.host, host)
138	            && self
139	                .folded_path
140	                .as_deref()
141	                .filter(|_| case_folded_path)
142	                .or(self.path.as_deref())
143	                .is_none_or(|pattern| glob_matches(pattern, path))
144	    }
145	
146	    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
147	        self.specificity.cmp(&other.specificity)
148	    }
149	}
