151	pub(crate) fn find_conflict(
152	    rules: &[CompiledRule],
153	) -> Result<Option<(usize, usize)>, ConflictCheckError> {
154	    let mut remaining_glob_overlap_states = MAX_TOTAL_GLOB_OVERLAP_STATES;
155	    for (right_index, right) in rules.iter().enumerate() {
156	        for (left_index, left) in rules[..right_index].iter().enumerate() {
157	            if left.action_class != right.action_class
158	                && left.specificity == right.specificity
159	                && methods_overlap(left.method.as_deref(), right.method.as_deref())
160	                && hosts_overlap(&left.host, &right.host)
161	            {
162	                match paths_overlap(
163	                    left.path.as_deref(),
164	                    right.path.as_deref(),
165	                    &mut remaining_glob_overlap_states,
166	                ) {
167	                    Ok(true) => return Ok(Some((left_index, right_index))),
168	                    Ok(false) => {}
169	                    Err(()) => {
170	                        return Err(ConflictCheckError::TooComplex {
171	                            first: left_index,
172	                            second: right_index,
173	                        });
174	                    }
175	                }
176	            }
177	        }
178	    }
179	    Ok(None)
180	}
181	
182	fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
183	    let host_kind = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
184	    let host_labels = match host {
185	        HostPattern::Bare(value) | HostPattern::Exact(value) | HostPattern::AnySubdomain(value) => {
186	            value.split('.').count()
187	        }
188	    };
189	    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
190	        None => (0, 0, 0, 0),
191	        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
192	        Some(value) => (
193	            1,
194	            value.bytes().filter(|byte| *byte != b'*').count(),
195	            value.bytes().filter(|byte| *byte == b'*').count(),
196	            value.find('*').unwrap_or(0),
197	        ),
198	    };
199	    Specificity {
200	        host_kind,
201	        host_labels,
202	        path_kind,
203	        literal_count,
204	        inverted_wildcard_count: usize::MAX - wildcard_count,
205	        literal_prefix,
206	        method: u8::from(has_method),
207	    }
208	}
209	
210	fn host_matches(pattern: &HostPattern, host: &str) -> bool {
211	    match pattern {
212	        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
213	        HostPattern::AnySubdomain(base) => host
214	            .strip_suffix(base)
215	            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
216	    }
217	}
218	
219	fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
220	    left.is_none() || right.is_none() || left == right
221	}
222	
223	fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
224	    match (left, right) {
225	        (HostPattern::Bare(a), HostPattern::Bare(b))
226	        | (HostPattern::Bare(a), HostPattern::Exact(b))
227	        | (HostPattern::Exact(a), HostPattern::Bare(b))
228	        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
229	        // These pairs cannot have equal host specificity, but retain correct
230	        // overlap semantics for callers that want them.
231	        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
232	        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
233	        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
234	        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
235	            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
236	        }
237	        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
238	            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
239	        }
240	    }
241	}
242	
243	fn paths_overlap(
244	    left: Option<&str>,
245	    right: Option<&str>,
246	    remaining_states: &mut usize,
247	) -> Result<bool, ()> {
248	    // Equal patterns always overlap. More importantly, this check must happen
249	    // before spending the bounded wildcard-analysis budget: an identical pair
250	    // is an unambiguous conflict, not an analysis failure.
251	    if left == right {
252	        return Ok(true);
253	    }
254	    match (left, right) {
255	        (None, _) | (_, None) => Ok(true),
256	        (Some(left), Some(right)) if !left.contains('*') && !right.contains('*') => Ok(false),
257	        (Some(left), Some(right)) if !left.contains('*') => Ok(glob_matches(right, left)),
258	        (Some(left), Some(right)) if !right.contains('*') => Ok(glob_matches(left, right)),
259	        (Some(left), Some(right)) => globs_overlap(left, right, remaining_states),
260	    }
261	}
262	
263	pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
264	    let pattern = pattern.as_bytes();
265	    let value = value.as_bytes();
266	    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
267	    while v < value.len() {
268	        while p < pattern.len() && pattern[p] == b'*' {
269	            star = Some(p);
270	            p += 1;
271	            retry = v;
272	        }
273	        if p < pattern.len() && pattern[p] == value[v] {
274	            p += 1;
275	            v += 1;
276	        } else if let Some(star_index) = star {
277	            p = star_index + 1;
278	            retry += 1;
279	            v = retry;
280	        } else {
281	            return false;
282	        }
283	    }
284	    while p < pattern.len() && pattern[p] == b'*' {
285	        p += 1;
286	    }
287	    p == pattern.len()
288	}
289	
290	/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
291	/// not currently present as a literal and keeps the alphabet finite.
292	const MAX_TOTAL_GLOB_OVERLAP_STATES: usize = 4_000_000;
293	
294	fn globs_overlap(left: &str, right: &str, remaining_states: &mut usize) -> Result<bool, ()> {
295	    let (left, right) = (left.as_bytes(), right.as_bytes());
296	    let width = right.len().checked_add(1).ok_or(())?;
297	    let states = left
298	        .len()
299	        .checked_add(1)
300	        .and_then(|height| height.checked_mul(width))
301	        .ok_or(())?;
302	    if states > *remaining_states {
303	        return Err(());
304	    }
305	    *remaining_states -= states;
306	    let mut seen = vec![false; states];
307	    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
308	    while let Some((i, j)) = queue.pop_front() {
309	        let state = i * width + j;
310	        if seen[state] {
311	            continue;
312	        }
313	        seen[state] = true;
314	        if i == left.len() && j == right.len() {
315	            return Ok(true);
316	        }
317	        if left.get(i) == Some(&b'*') {
318	            queue.push_back((i + 1, j));
319	        }
320	        if right.get(j) == Some(&b'*') {
321	            queue.push_back((i, j + 1));
322	        }
323	        let mut alphabet = vec![0];
324	        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
325	            alphabet.push(byte);
326	        }
327	        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
328	            alphabet.push(byte);
329	        }
330	        for byte in alphabet {
331	            let next_left = transition(left, i, byte);
332	            let next_right = transition(right, j, byte);
333	            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
334	                queue.push_back((next_left, next_right));
335	            }
336	        }
337	    }
338	    Ok(false)
339	}
340	
341	fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
342	    match pattern.get(index) {
343	        Some(b'*') => Some(index),
344	        Some(&literal) if literal == byte => Some(index + 1),
345	        _ => None,
346	    }
347	}
