32	/// A small, repeatable generator keeps this robustness coverage dependency-free.
33	fn generated_text(state: &mut u64, maximum_length: usize) -> String {
34	    const ALPHABET: &[char] = &[
35	        'a', 'Z', '0', '/', '.', '*', '%', ':', '@', ' ', '\\', '\0', '\n', 'é', '🦀',
36	    ];
37	    let length = usize::try_from(next(state)).unwrap_or(0) % (maximum_length + 1);
38	    (0..length)
39	        .map(|_| ALPHABET[usize::try_from(next(state)).unwrap_or(0) % ALPHABET.len()])
40	        .collect()
41	}
42	
43	fn generated_request(state: &mut u64) -> (String, String, String) {
44	    let method =
45	        ["GET", "POST", "DELETE", "get"][usize::try_from(next(state)).unwrap_or(0) % 4].to_owned();
46	    let host = ["api.acme.com", "x.acme.com", "a.b.acme.com", "acme.com"]
47	        [usize::try_from(next(state)).unwrap_or(0) % 4]
48	        .to_owned();
49	    let path = [
50	        "/v1/x",
51	        "/v1/refunds/r1",
52	        "/v1/%72efunds/r1",
53	        "/v1/../v1/x",
54	        "/",
55	    ][usize::try_from(next(state)).unwrap_or(0) % 5]
56	        .to_owned();
57	    if next(state) % 5 == 0 {
58	        (
59	            generated_text(state, 32),
60	            generated_text(state, 128),
61	            generated_text(state, 256),
62	        )
63	    } else {
64	        (method, host, path)
65	    }
66	}
67	
68	fn next(state: &mut u64) -> u64 {
69	    *state ^= *state << 13;
70	    *state ^= *state >> 7;
71	    *state ^= *state << 17;
72	    *state
73	}
74	
75	#[tokio::test]
76	async fn generated_inputs_never_panic_and_are_deterministic() {
77	    let classifier = load(&[PAYMENTS, REPOS]).await.unwrap();
78	    let mut state = 0x5EED_CAFE_BAAD_F00D;
79	    let mut classified = 0;
80	
81	    for _ in 0..2_000 {
82	        let (method, host, path) = generated_request(&mut state);
83	        let first = classifier.classify(&method, &host, &path).await;
84	        let second = classifier.classify(&method, &host, &path).await;
85	        assert_eq!(first, second, "{method:?} {host:?} {path:?}");
86	        assert!(first.is_none() || action_classifier::ACTION_CLASSES.contains(&first.unwrap()));
87	        classified += usize::from(first.is_some());
88	    }
