182	fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
183	    let host_kind = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
184	    let host_labels = match host {
185	        HostPattern::Bare(value) | HostPattern::Exact(value) | HostPattern::AnySubdomain(value) => {
186	            value.split('.').count()
187	        }
188	    };
189	    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
190	        None => (0, 0, 0, 0),
191	        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
192	        Some(value) => (
193	            1,
194	            value.bytes().filter(|byte| *byte != b'*').count(),
195	            value.bytes().filter(|byte| *byte == b'*').count(),
196	            value.find('*').unwrap_or(0),
197	        ),
198	    };
199	    Specificity {
200	        host_kind,
201	        host_labels,
202	        path_kind,
203	        literal_count,
204	        inverted_wildcard_count: usize::MAX - wildcard_count,
205	        literal_prefix,
206	        method: u8::from(has_method),
207	    }
208	}
