210	fn host_matches(pattern: &HostPattern, host: &str) -> bool {
211	    match pattern {
212	        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
213	        HostPattern::AnySubdomain(base) => host
214	            .strip_suffix(base)
215	            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
216	    }
217	}
