219	fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
220	    left.is_none() || right.is_none() || left == right
221	}
222	
223	fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
224	    match (left, right) {
225	        (HostPattern::Bare(a), HostPattern::Bare(b))
226	        | (HostPattern::Bare(a), HostPattern::Exact(b))
227	        | (HostPattern::Exact(a), HostPattern::Bare(b))
228	        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
229	        // These pairs cannot have equal host specificity, but retain correct
230	        // overlap semantics for callers that want them.
231	        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
232	        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
233	        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
234	        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
235	            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
236	        }
237	        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
238	            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
239	        }
240	    }
241	}
242	
243	fn paths_overlap(
244	    left: Option<&str>,
245	    right: Option<&str>,
246	    remaining_states: &mut usize,
247	) -> Result<bool, ()> {
248	    // Equal patterns always overlap. More importantly, this check must happen
249	    // before spending the bounded wildcard-analysis budget: an identical pair
250	    // is an unambiguous conflict, not an analysis failure.
251	    if left == right {
252	        return Ok(true);
253	    }
254	    match (left, right) {
255	        (None, _) | (_, None) => Ok(true),
256	        (Some(left), Some(right)) if !left.contains('*') && !right.contains('*') => Ok(false),
257	        (Some(left), Some(right)) if !left.contains('*') => Ok(glob_matches(right, left)),
258	        (Some(left), Some(right)) if !right.contains('*') => Ok(glob_matches(left, right)),
259	        (Some(left), Some(right)) => globs_overlap(left, right, remaining_states),
260	    }
261	}
262	
263	pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
264	    let pattern = pattern.as_bytes();
265	    let value = value.as_bytes();
266	    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
267	    while v < value.len() {
268	        while p < pattern.len() && pattern[p] == b'*' {
269	            star = Some(p);
270	            p += 1;
271	            retry = v;
272	        }
273	        if p < pattern.len() && pattern[p] == value[v] {
274	            p += 1;
275	            v += 1;
276	        } else if let Some(star_index) = star {
277	            p = star_index + 1;
278	            retry += 1;
279	            v = retry;
280	        } else {
281	            return false;
282	        }
283	    }
284	    while p < pattern.len() && pattern[p] == b'*' {
285	        p += 1;
286	    }
287	    p == pattern.len()
288	}
