1	//! Parsing and validation for mapping-set TOML documents.
2	
3	use serde::Deserialize;
4	
5	use crate::{ACTION_CLASSES, SetError, diagnostic_value, normalize};
6	
7	#[derive(Debug, Deserialize)]
8	#[serde(deny_unknown_fields)]
9	pub(crate) struct MappingSet {
10	    pub(crate) format_version: u32,
11	    pub(crate) name: String,
12	    pub(crate) description: Option<String>,
13	    pub(crate) host: String,
14	    pub(crate) rules: Vec<Rule>,
15	}
16	
17	#[derive(Debug, Deserialize)]
18	#[serde(deny_unknown_fields)]
19	pub(crate) struct Rule {
20	    pub(crate) method: Option<String>,
21	    pub(crate) subdomain: Option<String>,
22	    pub(crate) path: Option<String>,
23	    pub(crate) action_class: String,
24	}
25	
26	/// Converts one TOML document to a checked mapping set. Errors carry the
27	/// set's declared name when the document parsed far enough to have one.
28	pub(crate) fn parse(input: &str) -> Result<MappingSet, (Option<String>, SetError)> {
29	    let set: MappingSet = toml::from_str(input).map_err(|error| (None, SetError::Toml(error)))?;
30	    match validate(&set) {
31	        Ok(()) => Ok(set),
32	        Err(error) => Err((Some(set.name), error)),
33	    }
34	}
35	
36	fn validate(set: &MappingSet) -> Result<(), SetError> {
37	    if set.format_version != 1 {
38	        return Err(SetError::UnsupportedFormatVersion(set.format_version));
39	    }
40	    required_text("name", &set.name)?;
41	    if set
42	        .description
43	        .as_deref()
44	        .is_some_and(|description| description.chars().any(char::is_control))
45	    {
46	        return Err(SetError::InvalidField("description"));
47	    }
48	    validate_host(&set.host)?;
49	    if set.rules.is_empty() {
50	        return Err(SetError::InvalidField("rules"));
51	    }
52	
53	    for (index, rule) in set.rules.iter().enumerate() {
54	        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
55	            return Err(SetError::UnknownActionClass {
56	                rule: index,
57	                action_class: diagnostic_value(&rule.action_class),
58	            });
59	        }
60	        if let Some(method) = &rule.method
61	            && (method == "*" || normalize::method(method).is_none())
62	        {
63	            return Err(SetError::InvalidRule {
64	                rule: index,
65	                field: "method",
66	                value: diagnostic_value(method),
67	            });
68	        }
69	        if let Some(subdomain) = &rule.subdomain
70	            && subdomain != "*"
71	            && (subdomain.parse::<std::net::Ipv4Addr>().is_ok()
72	                || !is_dns_name(subdomain)
73	                || normalize::host(&format!("{subdomain}.{}", set.host)).is_none())
74	        {
75	            return Err(SetError::InvalidRule {
76	                rule: index,
77	                field: "subdomain",
78	                value: diagnostic_value(subdomain),
79	            });
80	        }
81	        if let Some(path) = &rule.path {
82	            let Some(normalized) = normalize::pattern_path(path) else {
83	                return Err(SetError::InvalidRule {
84	                    rule: index,
85	                    field: "path",
86	                    value: diagnostic_value(path),
87	                });
88	            };
89	            if normalized.len() > normalize::MAX_PATTERN_BYTES {
90	                return Err(SetError::InvalidRule {
91	                    rule: index,
92	                    field: "path",
93	                    value: diagnostic_value(path),
94	                });
95	            }
96	        }
97	    }
98	    Ok(())
99	}
100	
101	fn required_text(field: &'static str, value: &str) -> Result<(), SetError> {
102	    if value.trim().is_empty() || value.chars().any(char::is_control) {
103	        Err(SetError::InvalidField(field))
104	    } else {
105	        Ok(())
106	    }
107	}
108	
109	fn validate_host(host: &str) -> Result<(), SetError> {
110	    // Mapping hosts name an origin, not an HTTP authority. Ports and trailing
111	    // dots are accepted for request authorities but create duplicate mapping
112	    // identities, so reject them here.
113	    if !host.contains(':')
114	        && !host.ends_with('.')
115	        && normalize::host(host).is_some()
116	        && is_dns_name(host)
117	        && host.split('.').count() >= 2
118	    {
119	        Ok(())
120	    } else {
121	        Err(SetError::InvalidField("host"))
122	    }
123	}
124	
125	fn is_dns_name(value: &str) -> bool {
126	    !value.is_empty() && value.len() <= 253 && value.split('.').all(is_dns_label)
127	}
128	
129	fn is_dns_label(value: &str) -> bool {
130	    !value.is_empty()
131	        && value.len() <= 63
132	        && !value.starts_with('-')
133	        && !value.ends_with('-')
134	        && value
135	            .bytes()
136	            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
137	}
138	
139	#[cfg(test)]
140	mod tests {
141	    use super::parse;
142	
143	    const VALID: &str = r#"
144	format_version = 1
145	name = "Acme"
146	description = "Acme API"
147	host = "acme.com"
148	
149	[[rules]]
150	action_class = "payment.read"
151	"#;
152	
153	    #[test]
154	    fn parses_a_valid_mapping_set() {
155	        let set = parse(VALID).unwrap();
156	        assert_eq!(set.host, "acme.com");
157	        assert_eq!(set.rules.len(), 1);
158	    }
159	
160	    #[test]
161	    fn rejects_missing_required_top_level_fields() {
162	        for field in [
163	            "format_version = 1\n",
164	            "name = \"Acme\"\n",
165	            "host = \"acme.com\"\n",
166	        ] {
167	            let input = VALID.replace(field, "");
168	            assert!(parse(&input).is_err(), "expected {field:?} to be required");
169	        }
170	        assert!(
171	            parse(
172	                r#"
173	format_version = 1
174	name = "Acme"
175	description = "Acme API"
176	host = "acme.com"
177	"#
178	            )
179	            .is_err()
180	        );
181	        assert!(
182	            parse(
183	                r#"
184	format_version = 1
185	name = "Acme"
186	description = "Acme API"
187	host = "acme.com"
188	rules = []
189	"#
190	            )
191	            .is_err()
192	        );
193	    }
194	
195	    #[test]
196	    fn accepts_an_omitted_or_empty_description() {
197	        let omitted = VALID.replace("description = \"Acme API\"\n", "");
198	        assert_eq!(parse(&omitted).unwrap().description, None);
199	
200	        let empty = VALID.replace("description = \"Acme API\"", "description = \"\"");
201	        assert_eq!(parse(&empty).unwrap().description.as_deref(), Some(""));
202	    }
