//! Deterministic generated-input checks for the public API.

use action_classifier::load;

const PAYMENTS: &str = r#"
format_version = 1
name = "Payments"
host = "acme.com"

[[rules]]
subdomain = "api"
path = "/v1/*"
action_class = "payment.read"

[[rules]]
subdomain = "api"
method = "POST"
path = "/v1/refunds/*"
action_class = "payment.refund"
"#;

const REPOS: &str = r#"
format_version = 1
name = "Repos"
host = "acme.com"

[[rules]]
subdomain = "*"
action_class = "repo.read"
"#;

/// A small, repeatable generator keeps this robustness coverage dependency-free.
fn generated_text(state: &mut u64, maximum_length: usize) -> String {
    const ALPHABET: &[char] = &[
        'a', 'Z', '0', '/', '.', '*', '%', ':', '@', ' ', '\\', '\0', '\n', 'é', '🦀',
    ];
    let length = usize::try_from(next(state)).unwrap_or(0) % (maximum_length + 1);
    (0..length)
        .map(|_| ALPHABET[usize::try_from(next(state)).unwrap_or(0) % ALPHABET.len()])
        .collect()
}

fn generated_request(state: &mut u64) -> (String, String, String) {
    let method =
        ["GET", "POST", "DELETE", "get"][usize::try_from(next(state)).unwrap_or(0) % 4].to_owned();
    let host = ["api.acme.com", "x.acme.com", "a.b.acme.com", "acme.com"]
        [usize::try_from(next(state)).unwrap_or(0) % 4]
        .to_owned();
    let path = [
        "/v1/x",
        "/v1/refunds/r1",
        "/v1/%72efunds/r1",
        "/v1/../v1/x",
        "/",
    ][usize::try_from(next(state)).unwrap_or(0) % 5]
        .to_owned();
    if next(state) % 5 == 0 {
        (
            generated_text(state, 32),
            generated_text(state, 128),
            generated_text(state, 256),
        )
    } else {
        (method, host, path)
    }
}

fn next(state: &mut u64) -> u64 {
    *state ^= *state << 13;
    *state ^= *state >> 7;
    *state ^= *state << 17;
    *state
}

#[tokio::test]
async fn generated_inputs_never_panic_and_are_deterministic() {
    let classifier = load(&[PAYMENTS, REPOS]).await.unwrap();
    let mut state = 0x5EED_CAFE_BAAD_F00D;
    let mut classified = 0;

    for _ in 0..2_000 {
        let (method, host, path) = generated_request(&mut state);
        let first = classifier.classify(&method, &host, &path).await;
        let second = classifier.classify(&method, &host, &path).await;
        assert_eq!(first, second, "{method:?} {host:?} {path:?}");
        assert!(first.is_none() || action_classifier::ACTION_CLASSES.contains(&first.unwrap()));
        classified += usize::from(first.is_some());
    }
    assert!(
        classified >= 500,
        "only {classified} generated requests matched"
    );
}

#[tokio::test]
async fn generated_inputs_are_independent_of_mapping_set_order() {
    let forward = load(&[PAYMENTS, REPOS]).await.unwrap();
    let reverse = load(&[REPOS, PAYMENTS]).await.unwrap();
    let mut state = 0x1234_5678_9ABC_DEF0;

    for _ in 0..2_000 {
        let (method, host, path) = generated_request(&mut state);
        assert_eq!(
            forward.classify(&method, &host, &path).await,
            reverse.classify(&method, &host, &path).await,
            "{method:?} {host:?} {path:?}"
        );
    }
}

//! Requests that spell the same operation differently must not reach a
//! broader, less sensitive rule than the canonical spelling does.

use action_classifier::load;

const ACME: &str = r#"
format_version = 1
name = "Acme Payments"
description = "Acme payments API"
host = "acme.com"

[[rules]]
subdomain = "api"
path = "/v1/*"
action_class = "payment.read"

[[rules]]
subdomain = "api"
path = "/v1/refunds/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
method = "DELETE"
path = "/v1/charges/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
path = "/v1/payouts"
action_class = "payment.create"
"#;

#[tokio::test]
async fn percent_encoded_unreserved_characters_match_their_decoded_form() {
    let c = load(&[ACME]).await.unwrap();
    for path in [
        "/v1/%72efunds/x",
        "/v1/%72%65%66%75%6E%64%73/x",
        "/v1/refunds/%78",
    ] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            Some("payment.refund"),
            "{path}"
        );
    }
}

#[tokio::test]
async fn method_case_does_not_fall_through_to_method_less_rule() {
    let c = load(&[ACME]).await.unwrap();
    for method in ["DELETE", "delete", "Delete"] {
        assert_eq!(
            c.classify(method, "api.acme.com", "/v1/charges/ch_1").await,
            Some("payment.refund"),
            "{method}"
        );
    }
}

#[tokio::test]
async fn empty_path_segments_are_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    for path in ["/v1//refunds/x", "//v1/refunds/x", "/v1/refunds//x"] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            None,
            "{path}"
        );
    }
}

#[tokio::test]
async fn trailing_slash_that_changes_the_class_is_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    // A request without a slash is classified as sent.
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts").await,
        Some("payment.create")
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts/").await,
        None
    );
    // No disagreement: both spellings are payment.read.
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/balance").await,
        Some("payment.read")
    );
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/balance/").await,
        Some("payment.read")
    );
}

